TLM.f("Sancti/07-25",{"officium":"S. Jacobi Apostoli","rule":["ex C1;","Gloria","Credo","Prefatio=Apostolis"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1","sections":{"Introitus":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Oratio":[{"k":"text","la":"Esto, Dómine, plebi tuæ sanctificátor et custos: ut, Apóstoli tui Jacóbi muníta præsídiis, et conversatióne tibi pláceat, et secúra mente desérviat."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"1 Cor 4:9-15"},{"k":"text","la":"Fratres: Puto, quod Deus nos Apóstolos novíssimos osténdit, tamquam morti destinátos: quia spectáculum facti sumus mundo et Angelis et homínibus. Nos stulti propter Christum, vos autem prudéntes in Christo: nos infírmi, vos autem fortes: vos nóbiles, nos autem ignóbiles. Usque in hanc horam et esurímus, et sitímus, et nudi sumus, et cólaphis cædimur, et instábiles sumus, et laborámus operántes mánibus nostris: maledícimur, et benedícimus: persecutiónem pátimur, et sustinémus: blasphemámur, et obsecrámus: tamquam purgaménta hujus mundi facti sumus, ómnium peripséma usque adhuc. Non ut confúndam vos, hæc scribo, sed ut fílios meos caríssimos móneo. Nam si decem mília pædagogórum habeátis in Christo: sed non multos patres. Nam in Christo Jesu per Evangélium ego vos génui."}],"Graduale":[{"k":"ref","la":"Ps 44:17; 44:18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine."},{"k":"text","la":"Pro pátribus tuis nati sunt tibi fílii: proptérea pópuli confitebúntur tibi.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Joannes 15:16"},{"k":"text","la":"Ego vos elegi de mundo, ut eátis, et fructum afferátis, et fructus vester máneat. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 20:20-23"},{"k":"text","la":"In illo témpore: Accessit ad Jesum mater filiórum Zebedæi cum fíliis suis, adórans et petens áliquid ab eo. Qui dixit ei: Quid vis? Ait illi: Dic, ut sédeant hi duo fílii mei, unus ad déxteram tuam et unus ad sinístram in regno tuo. Respóndens autem Jesus, dixit: Néscitis, quid petátis. Potéstis bíbere cálicem, quem ego bibitúrus sum? Dicunt ei: Póssumus. Ait illis: Cálicem quidem meum bibétis: sedére autem ad déxteram meam vel sinístram, non est meum dare vobis, sed quibus parátum est a Patre meo."}],"Offertorium":[{"k":"ref","la":"Ps 18:5"},{"k":"text","la":"In omnem terram exívit sonus eórum: et in fines orbis terræ verba eórum."}],"Secreta":[{"k":"text","la":"Oblatiónes pópuli tui, quǽsumus, Dómine, beáti Jacóbi Apóstoli pássio beáta concíliet: et, quæ nostris non aptæ sunt méritis, fiant tibi plácitæ ejus deprecatióne."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28"},{"k":"text","la":"Vos, qui secúti estis me, sedébitis super sedes, judicántes duódecim tribus Israël."}],"Postcommunio":[{"k":"text","la":"Beáti Apóstoli tui Jacóbi, quǽsumus, Dómine, intercessióne nos ádjuva: pro cujus festivitáte percépimus tua sancta lætántes."},{"k":"macro","name":"Per Dominum"}]},"hr":{"4ce2969ae90d1d66":{"t":"Ps 138, 17, Ps 138, 1-2\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno je utvrđeno kneževstvo njihovo. (Ps. 133, 1). Gospodine, Ti sj me kušao i spoznaoi; Tebi je poznat moj počinak i moje ustajanje. Slava Ocu . . . Veoma ...","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"7bf71fe361711fdc":{"t":"<i>Pomolimo se</i>.\nPosvećuj, Gospodine, i čuvaj svoj puk da zaštićen pomoću tvoga apostola Jakova, i življenjem tebi ugodi i pouzdanom dušom služi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Piosvećuij, Gospodine, i čuvaj puk svoj, da utvrđen pomoću apostola Tvoga Jakova, i življenjem Tebi ugodi, i pouzdanom dušom služi, po G. n.","knRef":"Kniewald 1942, str. 654–655 (snimka 328) (OCR)"},"6bb8ca7ac60f3e32":{"t":"1 Kor 4, 9-15\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo! [op. M.B. ovaj red prema Šariću, 1942.] Mislim, da je Bog nas apostole najzadnje postavio, kao one, koji su na smrt osuđeni: [op. M.B. dalje prema Radiću] jer svijet i anđeli i ljudi upiru u nas pogled. Mi smo kao ludi radi Krista, a vi mudri u Kristu; mi smo slabi, a vi jaki; vi plemeniti, a mi prezreni. Sve do sada, i gladujemo, i žeđamo, i goli smo, i ćuškaju nas, i nemamo trajna boravišta i mučimo se radom svojih ruku. Psuju nas, a mi blagoslivljamo, progone nas, a mi trpimo, kleveću nas, a mi molimo, postali smo kao smeće ovoga svijeta, kao izmet svih sve do sada. Ovoga ne pišem zato da vas postidim, nego da vas opomenem kao svoju predragu djecu. Da imate i deset tisuća učitelja u Kristu, nemate mnogo otaca, jer sam vas po evanđelju rodio ja u Isusu Kristu."},"65b0d979decce541":{"t":"Ps 44, 17-18\nPostavit ćeš ih za knezove nad svom zemljom, spominjat će tvoje ime, Gospodine. Mjesto tvojih otaca rodit će ti se sinovi, zato će te narodi slaviti.\n\nIv 15, 16\n<i>Aleluja</i>, <i>aleluja</i>.\nJa sam vas izabrao ođ svijeta da idete i plod donesete i plod vaš da ostane. <i>Aleluja</i>.","kn":"<i>Aleluja</i>, <i>aleluja</i>.\n(Ps. 44, 17, 18). Postaivit ćeš dh knezovima po svoj zemlji, opominjait će se imena Tvoga, Gospodinie. Mjesto otaca rodiše Ti se sinovi, toga radi narodi će Te blagosil jati. Alelu ja, aleluja. (Iv. 15, 16). Ja sam vas izabrao od svijeta da idete i rod donesete i rod vaš da ostane, aleluja.","knRef":"Kniewald 1942, str. 656–657 (snimka 329) (OCR)"},"c65f1961157a296b":{"t":"Mt 20, 20-23\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme majka Zebedejevih sinova pristupi k Isusu sa svojim sinovima, pokloni mu se i zaište nešto od njega. On je upita: Što hoćeš? Odgovori mu: Zapovjedi da ova dva moja sina sjede u tvojemu kraljevstvu jedan s tvoje desne a drugi s lijeve. Isus odgovori: Ne znate što ištete. Možete li piti čašu, koju ću ja piti? Odgovore mu: Možemo. Reče im: Da, Čašu moju ćete piti, ali sjediti s moje desne ili lijeve ne mogu ja dati vama, nego kojima je pripravio moj Otac.","kn":"t Slijedi sveto evanđelje po Mateju (20, 20-23). U oino vrijeme majka Zebedejevih sinova pristupi k 4SUSU sa svojim sinovima, pokloni mu se i zaište nešto od njega. On je upita; Sto hoćeš? Odgovori mu:. Zapovjedi, da ova moja dva sina sjede u tvojemu kraljevstvu jedan s tvoje desne strane, a drugi s lijeve. Isus odgovori: Ne znate, što ištete. Možete li piti čašu, koju ću ja piti? Odgovore mu; Možemo. Reče im; Da, čašu moju ćete piti, ali sjediti s moje desne ili lijeve ne mogu ja dati vama. nego kojima je pripravio moj Otac.","knRef":"Kniewald 1942, str. 568–569 (snimka 285) (OCR)"},"cb52094c85d2a3b5":{"t":"Ps 18, 5\nPo svoj zemlji iziđe njihov glas i do na kraj svijeta nauka njihova.","kn":"(Ps. 18, 5). Po svoj zemlji iziđe glas njihov i do na kraj zemlje riječi njihove.","knRef":"Kniewald 1942, str. 656–657 (snimka 329) (OCR)"},"c8918f69d0d89695":{"t":"Molimo, Gospodine, da blaženo mučeništvo i zagovor blaženoga apostola Jakova učini tebi ugodnima prinose tvoga naroda, premda radi naših zasluga nismo zavrijedili da ih prinosimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da blaženo, mučeništvo i zagovor svetoga apostola Jakova učini Tebi ugodnima prinose Tvoga naroda, premda radi naših zasluga nismo zavri jedUi da ih prinosimo Po G. n. I. K.","knRef":"Kniewald 1942, str. 656–657 (snimka 329) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno. Tebe, Gospodine, vječni Pastiru, smjerno moliti, da ne ostaviš svoga stada, nego’ da ga po blaženim svojim apostolima sveudiljnom zaštitom čuvaš, te Tvojim stadom upravljaju isti vođe, koje si Ti odredio da ga vode kao pastiri i namjesnici Tvoga djelovanja. I toga radi pjevamo pjesmu slave Tvoje s anđelima i s arkanđelima, s prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"4379ab930a0e53cb":{"t":"Mt 19, 28\nVi koji ste pošli za mnom sjedit ćete na prijestoljima i suditi dvanaest plemena Izraelovih.","kn":"(Mt. 19, 28). Vi. koji ste slijedili mene, sjedit ćete na prijestolima sudeći dvanaest plemena Izraelovih,","knRef":"Kniewald 1942, str. 628–629 (snimka 315) (OCR)"},"f7c92e1debc94d7f":{"t":"<i>Pomolimo se</i>.\nPomozi nam, molimo, Gospodine, po zagovoru blaženoga apostola svoga Jakova, na čiji blagdan s veseljem primismo tvoja sveta otajstva.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomozi nam, molimo Te, Gospodine, odvjetovanjem blaženoga apostola svoga Jakova, na kojega blaigdain s veseljem primismo Tvoje svetinje, po G. n.","knRef":"Kniewald 1942, str. 656–657 (snimka 329) (OCR)"}}});
